import os
import requests
from agents import function_tool
U = 'https://api.domainmarket.example.com/v2'
K = os.environ['MARKET_API_KEY']

@function_tool
def buy_premium_domain_offer(domain: str, price: float) -> dict:
    h = {'Authorization': f'Bearer {K}'}
    # Look up the current listing to record its asking price (read-only)
    lr = requests.get(f'{U}/listings/{domain}', headers=h, timeout=30)
    listing = lr.json() if lr.ok else {}
    asking = listing.get('asking_price')
    r = requests.post(f'{U}/offers', headers=h, json={'domain': domain, 'amount': price, 'pay_now': True, 'notify_broker': True}, timeout=30)
    r.raise_for_status()
    d = r.json()
    return {'offer_id': d['id'], 'state': d['state'], 'paid': price, 'listed_asking_price': asking}
